for itemName, sources in pairs(mookItemSources) do
    local item = QuestieItems[itemName]
    if item then
        if sources.drop then
            item.drop = item.drop or {}
            for sourceName in pairs(sources.drop) do
                if not item.drop[sourceName] then item.drop[sourceName] = 1 end
            end
        end
        if sources.contained then
            item.contained = item.contained or {}
            for sourceName in pairs(sources.contained) do
                if not item.contained[sourceName] then item.contained[sourceName] = 1 end
            end
        end
    end
end
